// Pinterest pin images: tall 2:3 images with the page title over the hero photo.
// Generated by `npm run pins` (scripts/make-pins.mjs) into public/pins/. Dependency-free so the
// Node script can import it directly.

export const PIN_WIDTH = 1000;
export const PIN_HEIGHT = 1500;

export type PinCollection = 'destinations' | 'guides' | 'itineraries';

/** Public path of an entry's pin image. */
export const pinPath = (collection: PinCollection, id: string) => `/pins/${collection}-${id}.jpg`;

export const PIN_BOARDS: Record<PinCollection, string> = {
  destinations: 'Turkey destinations',
  guides: 'Turkey travel tips',
  itineraries: 'Turkey itineraries',
};

const escapeXml = (s: string) =>
  s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/** Greedy word wrap by character count; long words stay whole. Truncates with an ellipsis after maxLines. */
export function wrapText(text: string, maxChars: number, maxLines = Infinity): string[] {
  const lines: string[] = [];
  let line = '';
  for (const word of text.split(/\s+/).filter(Boolean)) {
    if (line && line.length + 1 + word.length > maxChars) {
      lines.push(line);
      line = word;
    } else {
      line = line ? `${line} ${word}` : word;
    }
  }
  if (line) lines.push(line);
  if (lines.length <= maxLines) return lines;
  const kept = lines.slice(0, maxLines);
  kept[maxLines - 1] = `${kept[maxLines - 1].replace(/[\s,.;:–-]+$/, '')}…`;
  return kept;
}

export interface PinText {
  eyebrow: string;
  title: string;
  summary: string;
  /** Shown at the foot of the pin, e.g. the site's domain. */
  footer: string;
  /** Photo credit, required by Creative Commons licences on adapted images. */
  credit: string;
}

/** SVG overlay drawn on top of the cropped hero photo. */
export function pinOverlaySvg(t: PinText): string {
  // Character counts per line are tuned to the 860px text column at each font size.
  const titleSize = t.title.length > 48 ? 80 : 96;
  const titleLines = wrapText(t.title, titleSize === 80 ? 21 : 18, 4);
  const summaryLines = wrapText(t.summary, 44, 4);
  const titleLead = titleSize * 1.08;
  const summaryLead = 46;

  // Text block sits at the bottom; compute from the foot upwards.
  const footerY = PIN_HEIGHT - 70;
  const summaryTop = footerY - 80 - summaryLines.length * summaryLead;
  const titleTop = summaryTop - 40 - titleLines.length * titleLead;
  const eyebrowY = titleTop - 30;
  const panelTop = eyebrowY - 90;

  const tspans = (lines: string[], x: number, y: number, lead: number) =>
    lines.map((l, i) => `<tspan x="${x}" y="${y + i * lead}">${escapeXml(l)}</tspan>`).join('');

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${PIN_WIDTH}" height="${PIN_HEIGHT}" viewBox="0 0 ${PIN_WIDTH} ${PIN_HEIGHT}">
  <defs>
    <linearGradient id="shade" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#0f2342" stop-opacity="0"/>
      <stop offset="0.35" stop-color="#0f2342" stop-opacity="0.82"/>
      <stop offset="1" stop-color="#0f2342" stop-opacity="0.96"/>
    </linearGradient>
  </defs>
  <rect x="0" y="${panelTop - 160}" width="${PIN_WIDTH}" height="${PIN_HEIGHT - panelTop + 160}" fill="url(#shade)"/>
  <rect x="70" y="${eyebrowY - 52}" width="90" height="8" fill="#e2a42b"/>
  <text x="70" y="${eyebrowY}" font-family="Segoe UI, Helvetica, Arial, sans-serif" font-size="34" font-weight="700" letter-spacing="3" fill="#e2a42b">${escapeXml(t.eyebrow.toUpperCase())}</text>
  <text font-family="Georgia, 'Times New Roman', serif" font-size="${titleSize}" fill="#fffbf4">${tspans(titleLines, 70, titleTop + titleSize, titleLead)}</text>
  <text font-family="Segoe UI, Helvetica, Arial, sans-serif" font-size="36" fill="#f3e7d3">${tspans(summaryLines, 70, summaryTop + 36, summaryLead)}</text>
  <text x="70" y="${footerY}" font-family="Segoe UI, Helvetica, Arial, sans-serif" font-size="34" font-weight="700" fill="#fffbf4">${escapeXml(t.footer)}</text>
  <text x="${PIN_WIDTH - 30}" y="${PIN_HEIGHT - 24}" text-anchor="end" font-family="Segoe UI, Helvetica, Arial, sans-serif" font-size="20" fill="#c9bba6">${escapeXml(t.credit)}</text>
</svg>`;
}

export interface PinRow {
  title: string;
  mediaUrl: string;
  board: string;
  description: string;
  link: string;
  keywords: string[];
}

const csvCell = (value: string) => (/[",\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value);

/** CSV in the column layout of Pinterest's bulk pin upload. */
export function pinsCsv(rows: PinRow[]): string {
  const header = ['Title', 'Media URL', 'Pinterest board', 'Thumbnail', 'Description', 'Link', 'Publish date', 'Keywords'];
  const lines = rows.map((r) =>
    [r.title.slice(0, 100), r.mediaUrl, r.board, '', r.description.slice(0, 500), r.link, '', r.keywords.join(', ')]
      .map(csvCell)
      .join(','),
  );
  return [header.join(','), ...lines].join('\n') + '\n';
}
